async (page) => {
await page.selectOption('#'+ (await page.getByLabel('Category').getAttribute('id')) , {label:'Tents'}).catch(async()=>{await page.getByLabel('Category').selectOption({label:'Tents'})});
await page.getByLabel('Minimum rating').selectOption({label:'4+'});
await page.getByLabel('In stock only').check();
await page.getByLabel('Sort').selectOption({label:'Price: low to high'});
await page.getByRole('button',{name:'Apply filters'}).click();
await page.waitForTimeout(1000);
const out=[];
const pages = await page.locator('main button:not(:has-text("Apply"))').count();
out.push('pages:'+pages);
for (let i=0;i<Math.max(pages,1);i++){
 if(pages>0){ await page.locator('main button:not(:has-text("Apply"))').nth(i).click(); await page.waitForTimeout(700);}
 out.push(await page.locator('main').innerText());
}
return out.join('\n----\n');
}

